package com.ke.ticketsystemke.service;
import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.*;import com.ke.ticketsystemke.storage.WarrantyFileStorage;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.InputStreamResource;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import java.io.*;import java.time.*;import java.util.*;
@Service public class WarrantyAttachmentService{
 private final TicketRepository tickets;private final WarrantyClaimRepository claims;private final WarrantyReplacementRepository replacements;private final WarrantyAttachmentRepository attachments;private final EmployeeRepository employees;private final AccessService access;private final WarrantyClaimEventService audit;private final WarrantyFileStorage storage;private final WarrantyDocumentRequirementService requirements;private final long maxBytes,maxClaim,maxReplacement;
 public WarrantyAttachmentService(TicketRepository t,WarrantyClaimRepository c,WarrantyReplacementRepository r,WarrantyAttachmentRepository a,EmployeeRepository e,AccessService access,WarrantyClaimEventService audit,WarrantyFileStorage storage,WarrantyDocumentRequirementService requirements,@Value("${warranty.files.max-file-bytes:8388608}")long maxBytes,@Value("${warranty.files.max-claim-files:20}")long maxClaim,@Value("${warranty.files.max-replacement-files:10}")long maxReplacement){tickets=t;claims=c;replacements=r;attachments=a;employees=e;this.access=access;this.audit=audit;this.storage=storage;this.requirements=requirements;this.maxBytes=maxBytes;this.maxClaim=maxClaim;this.maxReplacement=maxReplacement;}
 @Transactional(readOnly=true)public WarrantyDocumentSummaryResponse summary(Long ticketId,Long claimId,String actor){view(actor);Context x=context(ticketId,claimId,false);WarrantyReplacement replacement=replacements.findByWarrantyClaim_IdAndActiveTrue(claimId).orElse(null);return requirements.summarize(x.claim(),replacement);}
 @Transactional(readOnly=true)public List<WarrantyAttachmentResponse> list(Long ticketId,Long claimId,WarrantyAttachmentCategory category,Long replacementId,boolean activeOnly,String actor){view(actor);Context x=context(ticketId,claimId,false);return attachments.findByWarrantyClaim_IdOrderByUploadedAtDesc(claimId).stream().filter(a->category==null||a.getCategory()==category).filter(a->replacementId==null||a.getWarrantyReplacement()!=null&&Objects.equals(a.getWarrantyReplacement().getId(),replacementId)).filter(a->!activeOnly||a.isActive()).map(WarrantyAttachmentResponse::from).toList();}
 @Transactional public WarrantyAttachmentResponse upload(Long ticketId,Long claimId,WarrantyAttachmentCategory category,Long replacementId,MultipartFile file,String actor){manage(actor);Context x=context(ticketId,claimId,true);WarrantyReplacement replacement=validateRelationship(claimId,category,replacementId);validateLimits(claimId,replacement,category,file);Detected d=detect(file);WarrantyFileStorage.StoredFile stored=null;try{stored=storage.store(claimId,file.getInputStream());WarrantyAttachment a=entity(x.claim(),replacement,category,file,d,stored,actor);dimensions(a);attachments.saveAndFlush(a);audit.record(x.claim(),WarrantyClaimEventType.WARRANTY_ATTACHMENT_UPLOADED,actor,"Warranty document uploaded",meta(a));return WarrantyAttachmentResponse.from(a);}catch(ResponseStatusException e){cleanup(stored);throw e;}catch(Exception e){cleanup(stored);throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Warranty file storage failed");}}
 @Transactional public WarrantyAttachmentResponse supersede(Long ticketId,Long claimId,Long attachmentId,MultipartFile file,String reason,Long version,String actor){manage(actor);Context x=context(ticketId,claimId,true);WarrantyAttachment old=attachment(claimId,attachmentId);if(!old.isActive())conflict("Inactive attachment cannot be superseded");if(!Objects.equals(old.getVersion(),version))conflict("Attachment was updated by another user");if(trim(reason)==null)bad("Supersede reason is required");Detected d=detect(file);WarrantyFileStorage.StoredFile stored=null;try{stored=storage.store(claimId,file.getInputStream());WarrantyAttachment n=entity(x.claim(),old.getWarrantyReplacement(),old.getCategory(),file,d,stored,actor);dimensions(n);old.setActive(false);old.setDeactivatedAt(Instant.now());old.setDeactivatedByEmployeeId(actor);old.setDeactivationReason(trim(reason));attachments.saveAndFlush(n);old.setSupersededByAttachmentId(n.getId());attachments.saveAndFlush(old);audit.record(x.claim(),WarrantyClaimEventType.WARRANTY_ATTACHMENT_SUPERSEDED,actor,"Warranty document superseded",Map.of("oldAttachmentId",old.getId(),"newAttachmentId",n.getId(),"category",old.getCategory(),"reason",trim(reason)));return WarrantyAttachmentResponse.from(n);}catch(Exception e){cleanup(stored);if(e instanceof ResponseStatusException r)throw r;throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Warranty file storage failed");}}
 @Transactional public void deactivate(Long ticketId,Long claimId,Long attachmentId,String reason,Long version,String actor){manage(actor);Context x=context(ticketId,claimId,true);WarrantyAttachment a=attachment(claimId,attachmentId);if(!a.isActive())conflict("Attachment is already inactive");if(!Objects.equals(a.getVersion(),version))conflict("Attachment was updated by another user");if(trim(reason)==null)bad("Removal reason is required");a.setActive(false);a.setDeactivatedAt(Instant.now());a.setDeactivatedByEmployeeId(actor);a.setDeactivationReason(trim(reason));attachments.saveAndFlush(a);audit.record(x.claim(),WarrantyClaimEventType.WARRANTY_ATTACHMENT_DEACTIVATED,actor,"Warranty document removed from current record",Map.of("attachmentId",a.getId(),"category",a.getCategory(),"reason",trim(reason)));}
 @Transactional(readOnly=true)public Content content(Long ticketId,Long claimId,Long attachmentId,boolean download,String actor){view(actor);context(ticketId,claimId,false);WarrantyAttachment a=attachment(claimId,attachmentId);try{InputStreamResource resource=new InputStreamResource(storage.open(a.getStorageKey()));String disposition=(download?"attachment":"inline")+"; filename=\""+safeHeader(a.getDisplayFilename())+"\"";return new Content(resource,MediaType.parseMediaType(a.getDetectedMimeType()),a.getSizeBytes(),disposition);}catch(IOException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty document content is unavailable");}}
 private WarrantyAttachment entity(WarrantyClaim c,WarrantyReplacement r,WarrantyAttachmentCategory category,MultipartFile f,Detected d,WarrantyFileStorage.StoredFile s,String actor){WarrantyAttachment a=new WarrantyAttachment();a.setWarrantyClaim(c);a.setWarrantyReplacement(r);a.setCategory(category);a.setOriginalFilename(filename(f.getOriginalFilename()));a.setDisplayFilename(filename(f.getOriginalFilename()));a.setStorageProvider("FILESYSTEM");a.setStorageKey(s.key());a.setDetectedMimeType(d.mime());a.setSizeBytes(s.sizeBytes());a.setChecksum(s.checksum());a.setUploadedByEmployeeId(actor);a.setUploadedByEmployeeName(employees.findByEmployeeIdIgnoreCase(actor).map(Employee::getName).orElse(null));return a;}
 private void dimensions(WarrantyAttachment a){if(!a.getDetectedMimeType().startsWith("image/"))return;try(InputStream in=storage.open(a.getStorageKey())){BufferedImage image=ImageIO.read(in);if(image!=null){a.setImageWidth(image.getWidth());a.setImageHeight(image.getHeight());}}catch(Exception ignored){}}
 private Detected detect(MultipartFile f){if(f==null||f.isEmpty())bad("File is required");if(f.getSize()>maxBytes)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Warranty document exceeds the configured size limit");try(InputStream raw=f.getInputStream();BufferedInputStream in=new BufferedInputStream(raw)){byte[] b=in.readNBytes(16);String mime=magic(b);if(mime==null)throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"Only JPEG, PNG, WebP, and PDF files are supported");String ext=extension(f.getOriginalFilename());if(!matches(ext,mime))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"Filename extension does not match detected file type");return new Detected(mime);}catch(IOException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unable to inspect uploaded file");}}
 private String magic(byte[] b){if(b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255)return"image/jpeg";if(b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return"image/png";if(b.length>=12&&new String(b,0,4).equals("RIFF")&&new String(b,8,4).equals("WEBP"))return"image/webp";if(b.length>=5&&new String(b,0,5).equals("%PDF-"))return"application/pdf";return null;}private boolean matches(String e,String m){return m.equals("image/jpeg")&&(e.equals("jpg")||e.equals("jpeg"))||m.equals("image/png")&&e.equals("png")||m.equals("image/webp")&&e.equals("webp")||m.equals("application/pdf")&&e.equals("pdf");}
 private void validateLimits(Long claimId,WarrantyReplacement r,WarrantyAttachmentCategory c,MultipartFile f){if(attachments.countByWarrantyClaim_IdAndActiveTrue(claimId)>=maxClaim)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Maximum active warranty documents reached");if(r!=null&&attachments.countByWarrantyReplacement_IdAndActiveTrue(r.getId())>=maxReplacement)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Maximum active replacement documents reached");if(c.isSingleCurrent()&&(r==null?attachments.existsByWarrantyClaim_IdAndWarrantyReplacementIsNullAndCategoryAndActiveTrue(claimId,c):attachments.existsByWarrantyReplacement_IdAndCategoryAndActiveTrue(r.getId(),c)))conflict("A current document already exists for this category; use replace");}
 private WarrantyReplacement validateRelationship(Long claimId,WarrantyAttachmentCategory c,Long replacementId){if(c.isReplacement()&&replacementId==null)bad("Replacement document category requires replacementId");if(!c.isReplacement()&&replacementId!=null)bad("Original warranty document category cannot reference a replacement");if(replacementId==null)return null;WarrantyReplacement r=replacements.findById(replacementId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Replacement not found"));if(!Objects.equals(r.getWarrantyClaim().getId(),claimId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Replacement not found");return r;}
 private Context context(Long ticketId,Long claimId,boolean edit){Ticket t=tickets.findById(ticketId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Ticket not found"));WarrantyClaim c=claims.findById(claimId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found"));if(!Objects.equals(c.getTicket().getId(),ticketId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Warranty claim not found");if(edit&&!c.isActive())conflict("Inactive warranty claims are read-only");return new Context(t,c);}private WarrantyAttachment attachment(Long claimId,Long id){WarrantyAttachment a=attachments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Attachment not found"));if(!Objects.equals(a.getWarrantyClaim().getId(),claimId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Attachment not found");return a;}
 private void view(String a){access.requireAllowed(a,AccessKey.VIEW_TICKETS);access.requireAllowed(a,AccessKey.VIEW_WARRANTY);}private void manage(String a){access.requireAllowed(a,AccessKey.VIEW_TICKETS);access.requireAllowed(a,AccessKey.MANAGE_WARRANTY_DOCUMENTS);}private Map<String,Object> meta(WarrantyAttachment a){Map<String,Object>m=new LinkedHashMap<>();m.put("attachmentId",a.getId());m.put("category",a.getCategory());m.put("displayFilename",a.getDisplayFilename());m.put("detectedMime",a.getDetectedMimeType());m.put("size",a.getSizeBytes());m.put("replacementId",a.getWarrantyReplacement()==null?"":a.getWarrantyReplacement().getId());return m;}private void cleanup(WarrantyFileStorage.StoredFile s){if(s!=null)try{storage.deletePermanent(s.key());}catch(IOException ignored){}}private String filename(String n){String v=trim(n);if(v==null)return"document";v=v.replace('\\','/');v=v.substring(v.lastIndexOf('/')+1).replaceAll("[\\r\\n\\t]","_");return v.length()>255?v.substring(v.length()-255):v;}private String extension(String n){String f=filename(n).toLowerCase(Locale.ROOT);int p=f.lastIndexOf('.');return p<0?"":f.substring(p+1);}private String safeHeader(String n){return filename(n).replace("\"","");}private String trim(String s){return s==null||s.trim().isEmpty()?null:s.trim();}private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}private record Context(Ticket ticket,WarrantyClaim claim){}private record Detected(String mime){}public record Content(InputStreamResource resource,MediaType mediaType,long length,String disposition){}
}
